CREATE POLICY "Anyone can read mod files bucket" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'mod-files');
CREATE POLICY "Admins can upload mod files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'mod-files' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can update mod files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'mod-files' AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'mod-files' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can delete mod files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'mod-files' AND public.has_role(auth.uid(), 'admin'));